"use strict";
document.addEventListener("click",event=>{const product=event.target.closest("[data-product]");if(product){event.preventDefault();event.stopImmediatePropagation();location.href="products/"+encodeURIComponent(product.dataset.product)+".html";return;}const contact=event.target.closest("[data-contact],.contact-open");if(contact){event.preventDefault();event.stopImmediatePropagation();location.href="contact.html";return;}const policy=event.target.closest("[data-policy]");if(policy){event.preventDefault();event.stopImmediatePropagation();location.href=(policy.dataset.policy==="terms"?"terms":"privacy")+".html";return;}const a=event.target.closest("a");if(!a)return;const map={"#about":"about.html","#products":"products.html","#science":"approach.html","#partnership":"partnership.html","#care":"care.html","#knowledge":"resources.html","#contact":"contact.html"};if(map[a.getAttribute("href")]){event.preventDefault();event.stopImmediatePropagation();location.href=map[a.getAttribute("href")];}},true);
const language=document.querySelector("#language");if(language){const text={en:["More knowledge.<br>A clearer next step.","Get to know our portfolio, explore animal care and find practical information for a better professional conversation.","Our company","Product details","Animal care","Knowledge centre"],fr:["Mieux comprendre.<br>Avancer avec clarté.","Découvrez notre gamme, les soins vétérinaires et des ressources pratiques pour préparer vos échanges professionnels.","Notre entreprise","Détails des produits","Santé animale","Centre de ressources"],ar:["معرفة أوسع.<br>خطوة أوضح.","تعرّف على مجموعة المنتجات ومجالات الرعاية والموارد العملية لتجهيز استفسارك المهني.","عن الشركة","تفاصيل المنتجات","رعاية الحيوان","مركز المعرفة"]};function updateDirectory(){const section=document.querySelector(".content-directory");if(!section)return;const t=text[language.value]||text.en;section.querySelector("h2").innerHTML=t[0];section.querySelector("div>p:not(.cd-eyebrow)").textContent=t[1];section.querySelectorAll(".cd-grid>a>span").forEach((s,i)=>s.textContent=t[i+2]);section.querySelectorAll(".cd-grid>a>p").forEach(p=>p.hidden=language.value!=="en");}language.addEventListener("change",updateDirectory);updateDirectory();}